class Solution:
    def countSubTrees(self, n: int, edges: list[list[int]], labels: str) -> list[int]:
        import sys
        sys.setrecursionlimit(200000)
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        ans = [0] * n
        def dfs(u, parent):
            counts = [0] * 26
            u_label = ord(labels[u]) - ord("a")
            counts[u_label] = 1
            for v in graph[u]:
                if v != parent:
                    child_counts = dfs(v, u)
                    for i in range(26):
                        counts[i] += child_counts[i]
            ans[u] = counts[u_label]
            return counts
        dfs(0, -1)
        return ans

#include <vector>
#include <string>

class Solution {
    std::vector<int> ans;
    std::vector<int> dfs(int u, int parent, const std::vector<std::vector<int>>& graph, const std::string& labels) {
        std::vector<int> counts(26, 0);
        int uLabel = labels[u] - 'a';
        counts[uLabel] = 1;
        for (int v : graph[u]) {
            if (v != parent) {
                auto childCounts = dfs(v, u, graph, labels);
                for (int i = 0; i < 26; ++i) counts[i] += childCounts[i];
            }
        }
        ans[u] = counts[uLabel];
        return counts;
    }
public:
    std::vector<int> countSubTrees(int n, std::vector<std::vector<int>>& edges, std::string labels) {
        std::vector<std::vector<int>> graph(n);
        for (const auto& e : edges) {
            graph[e[0]].push_back(e[1]);
            graph[e[1]].push_back(e[0]);
        }
        ans.assign(n, 0);
        dfs(0, -1, graph, labels);
        return ans;
    }
};

import java.util.*;

class Solution {
    int[] ans;
    private int[] dfs(int u, int parent, List<Integer>[] graph, String labels) {
        int[] counts = new int[26];
        int uLabel = labels.charAt(u) - 'a';
        counts[uLabel] = 1;
        for (int v : graph[u]) {
            if (v != parent) {
                int[] childCounts = dfs(v, u, graph, labels);
                for (int i = 0; i < 26; i++) counts[i] += childCounts[i];
            }
        }
        ans[u] = counts[uLabel];
        return counts;
    }
    public int[] countSubTrees(int n, int[][] edges, String labels) {
        List<Integer>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(e[1]);
            graph[e[1]].add(e[0]);
        }
        ans = new int[n];
        dfs(0, -1, graph, labels);
        return ans;
    }
}

